import{_ as d,o as e,c as o,a2 as c}from"./chunks/framework.Bg-Zxr5O.js";const A=JSON.parse('{"title":"附录","description":"","frontmatter":{},"headers":[],"relativePath":"tutorial/09-附录.md","filePath":"tutorial/09-附录.md","lastUpdated":1785684581000}'),r={name:"tutorial/09-附录.md"};function a(i,t,s,n,l,S){return e(),o("div",null,[...t[0]||(t[0]=[c(`<h1 id="附录" tabindex="-1">附录 <a class="header-anchor" href="#附录" aria-label="Permalink to &quot;附录&quot;">​</a></h1><h2 id="附录-a-·-pspp-命令速查表" tabindex="-1">附录 A · PSPP 命令速查表 <a class="header-anchor" href="#附录-a-·-pspp-命令速查表" aria-label="Permalink to &quot;附录 A · PSPP 命令速查表&quot;">​</a></h2><p>下表在提纲&quot;命令 → 菜单路径速查映射&quot;基础上扩展为三列：命令、语法功能、关键子命令或注意点。其中【手册明示】表示手册中确实出现过的菜单/对话框引用；【界面推断】表示按 PSPP/SPSS 通用界面结构推断，其依据为通用界面知识，手册未逐项文档化，实际菜单名称可能随版本略有差异。PSPP 命令统一以英文句点 <code>.</code> 结尾（<code>data&gt;</code> 提示符期间不要输入句点）。下表覆盖本书正文涉及的主要命令，未穷尽全部子命令；正文中已逐项展开的语法模板可与此表对照查阅。</p><table tabindex="0"><thead><tr><th>PSPP 命令</th><th>语法功能</th><th>关键子命令或注意点</th></tr></thead><tbody><tr><td><code>pspp</code> / <code>psppire</code></td><td>启动命令行 / 图形界面</td><td>【推断】经终端或开始菜单启动；<code>pspp</code> 为文本界面，<code>psppire</code> 为图形界面</td></tr><tr><td><code>DATA LIST</code> + <code>BEGIN DATA</code></td><td>定义变量并录入数据</td><td>【推断】对应 Variable View + Data View；<code>BEGIN DATA</code>/<code>END DATA</code> 须配对，<code>END DATA.</code> 独占一行</td></tr><tr><td><code>GET DATA /TYPE=ODS</code></td><td>导入 OpenDocument/Excel 表格</td><td>【推断】File → Import Data；<code>/TYPE</code> 须为首个，<code>/VARIABLES</code> 须放最后；<code>ASSUMEDSTRWIDTH</code> 易截断长文本，建议显式指定</td></tr><tr><td><code>GET DATA /TYPE=TXT</code></td><td>导入 CSV/定界文本</td><td>【推断】File → Import Data；<code>/DELIMITERS=</code> 用 <code>\\t</code> 表示制表符；遗漏 <code>/FIRSTCASE=2</code> 会把表头当数据读入</td></tr><tr><td><code>IMPORT</code></td><td>读取系统/便携文件</td><td>【推断】File → Open；仅读取 .sav 等 PSPP 文件，不能直接读 Excel/CSV，后者须用 <code>GET DATA</code></td></tr><tr><td><code>SORT CASES</code></td><td>排序个案</td><td>【手册明示】Data → Sort Cases；<code>(D)</code> 降序、<code>(A)</code> 升序（默认）；只改变活动数据集，不改原 .sav</td></tr><tr><td><code>SPLIT FILE</code></td><td>拆分文件分组输出</td><td>【推断】Data → Split File；<code>LAYERED</code> 合并于一张表、<code>SEPARATE</code> 各组独立表；持续生效至 <code>SPLIT FILE OFF.</code></td></tr><tr><td><code>SELECT IF</code> / <code>FILTER</code></td><td>选择 / 过滤个案</td><td>【推断】Data → Select Cases；<code>SELECT IF</code> 永久删除未选中个案，<code>FILTER</code> 仅隐藏、可 <code>FILTER OFF</code> 恢复</td></tr><tr><td><code>COMPUTE</code></td><td>计算新变量</td><td>【推断】Transform → Compute Variable；数值目标变量可自动新建，字符串目标变量须先以 <code>STRING</code> 声明</td></tr><tr><td><code>RECODE</code></td><td>重新编码</td><td>【推断】Transform → Recode；<code>THRU</code> 含端点，<code>ELSE</code> 须置于末组；省略 <code>INTO</code> 则就地改写</td></tr><tr><td><code>MISSING VALUES</code></td><td>定义缺失值</td><td>【推断】Variable View → Missing；数值至多 3 个离散值或一个范围；用户缺失默认在多数过程中被排除</td></tr><tr><td><code>VARIABLE LABELS</code> / <code>VALUE LABELS</code></td><td>变量标签 / 值标签</td><td>【推断】Variable View；<code>VALUE LABELS</code> 会清空已有值标签，追加请用 <code>ADD VALUE LABELS</code></td></tr><tr><td><code>FREQUENCIES</code></td><td>频率统计与图表</td><td>【推断】Analyze → Descriptive Statistics → Frequencies；<code>/HISTOGRAM</code>、<code>/PIECHART</code>、<code>/BARCHART</code>；对字符串变量不画直方图</td></tr><tr><td><code>DESCRIPTIVES</code></td><td>描述统计与 Z 分数</td><td>【推断】Analyze → Descriptive Statistics → Descriptives；<code>/SAVE</code> 写出 Z 分数新变量（如 Zheight）</td></tr><tr><td><code>EXAMINE</code></td><td>探索性分析与箱线/正态图</td><td>【推断】Analyze → Descriptive Statistics → Explore；\`/PLOT=BOXPLOT</td></tr><tr><td><code>CROSSTABS</code></td><td>交叉表与 χ² 检验</td><td>【推断】Analyze → Descriptive Statistics → Crosstabs；<code>/STATISTICS=CHISQ</code> 含 Pearson χ²、似然比、Fisher 精确等</td></tr><tr><td><code>MEANS</code></td><td>分组均值</td><td>【推断】Analyze → Compare Means → Means；<code>/CELLS=MEAN,STDDEV,SUM,MIN,MAX,…</code></td></tr><tr><td><code>T-TEST</code></td><td>t 检验（单样本/独立/配对）</td><td>【推断】Analyze → Compare Means → (One/Independent/Paired) Samples T Test；由 <code>TESTVAL=</code>/<code>GROUPS=</code>/<code>PAIRS=</code> 触发；独立样本自动含 Levene 方差齐性检验</td></tr><tr><td><code>NPAR TESTS</code></td><td>非参数检验</td><td>【推断】Analyze → Nonparametric Tests → …；<code>/CHISQUARE</code>、<code>/SIGN</code>、<code>/WILCOXON</code>、<code>/MANN-WHITNEY</code>、<code>/KOLMOGOROV-SMIRNOV</code></td></tr><tr><td><code>ONEWAY</code></td><td>单因素 ANOVA</td><td>【推断】Analyze → Compare Means → One-Way ANOVA；仅处理单因素，<code>/POSTHOC=TUKEY</code> 等，<code>/STATISTICS=HOMOGENEITY</code> 做 Levene</td></tr><tr><td><code>GLM</code></td><td>析因（双/多因素）ANOVA</td><td>【推断】Analyze → General Linear Model → Univariate；PSPP 中双因素须走 GLM；<code>/DESIGN=</code> 用 <code>*</code> 连接交互项</td></tr><tr><td><code>CORRELATIONS</code></td><td>Pearson 相关</td><td>【推断】Analyze → Correlate → Bivariate；<code>/PRINT=TWOTAIL SIG</code>；<code>/MISSING=PAIRWISE</code>（默认）</td></tr><tr><td><code>REGRESSION</code></td><td>线性 / 多元回归</td><td>【推断】Analyze → Regression → Linear；<code>/DEPENDENT=</code> 必填；<code>/SAVE=PRED RESID</code>；缺乏 <code>/SCATTERPLOT</code> 等诊断子命令</td></tr><tr><td><code>GRAPH /SCATTERPLOT</code></td><td>散点图</td><td>【推断】Graphs → Legacy Dialogs → Scatter/Dot；一次调用只能画一种图</td></tr><tr><td><code>GRAPH /HISTOGRAM</code></td><td>直方图</td><td>【推断】Graphs → Legacy Dialogs → Histogram；<code>(NORMAL)</code> 叠加正态曲线；仅接受单一变量</td></tr><tr><td><code>GRAPH /BAR</code></td><td>条形图</td><td>【推断】Graphs → Legacy Dialogs → Bar；第二分类变量产生簇状条图</td></tr><tr><td><code>FREQUENCIES /PIECHART</code></td><td>饼图（唯一途径）</td><td>【推断】Analyze → Descriptive Statistics → Frequencies → Charts；<code>GRAPH</code> 本身无饼图子命令，饼图只能走 FREQUENCIES</td></tr></tbody></table><h3 id="pspp-当前未实现的过程" tabindex="-1">PSPP 当前未实现的过程 <a class="header-anchor" href="#pspp-当前未实现的过程" aria-label="Permalink to &quot;PSPP 当前未实现的过程&quot;">​</a></h3><p>PSPP 并非 SPSS 的完整克隆，部分 SPSS 过程在 PSPP 中尚未实现。双因素或多因素方差分析不能依赖 <code>ANOVA</code> 或 <code>UNIANOVA</code>（二者均未实现），应改用 <code>GLM</code> 并在 <code>/DESIGN</code> 中写明交互项（如 <code>a*b</code>）。原始 GPL 自定义作图命令 <code>GGRAPH</code>、<code>IGRAPH</code>、<code>XGRAPH</code> 均不可用；茎叶图命令 <code>STEMLEAF</code> 不可用；SPSS 式的多格式导入命令 <code>GET TRANSLATE</code> 亦不可用。此外，手册还列出 <code>MANOVA</code>、<code>MULT RESPONSE</code>、<code>CURVEFIT</code>、<code>PPLOT</code> 等同样未实现。涉及上述过程时，应避免在教程中描述成 PSPP 可直接完成的操作，必要时应提示读者改用替代命令或手工处理，并明确说明&quot;PSPP 当前不支持&quot;。</p><h2 id="附录-b-·-常用统计术语中英对照" tabindex="-1">附录 B · 常用统计术语中英对照 <a class="header-anchor" href="#附录-b-·-常用统计术语中英对照" aria-label="Permalink to &quot;附录 B · 常用统计术语中英对照&quot;">​</a></h2><p>以下术语在本书正文与 PSPP 对话框中频繁出现，统一对照如下，便于读者在英文界面与中文资料之间切换。</p><table tabindex="0"><thead><tr><th>中文术语</th><th>英文术语</th></tr></thead><tbody><tr><td>变量</td><td>variable</td></tr><tr><td>个案</td><td>case</td></tr><tr><td>数据集</td><td>dataset</td></tr><tr><td>变量标签</td><td>variable label</td></tr><tr><td>值标签</td><td>value label</td></tr><tr><td>缺失值</td><td>missing value</td></tr><tr><td>均值</td><td>mean</td></tr><tr><td>标准差</td><td>standard deviation</td></tr><tr><td>方差</td><td>variance</td></tr><tr><td>中位数</td><td>median</td></tr><tr><td>众数</td><td>mode</td></tr><tr><td>偏度</td><td>skewness</td></tr><tr><td>峰度</td><td>kurtosis</td></tr><tr><td>显著性</td><td>significance</td></tr><tr><td>p 值</td><td>p-value</td></tr><tr><td>置信区间</td><td>confidence interval</td></tr><tr><td>效应量</td><td>effect size</td></tr><tr><td>相关系数</td><td>correlation coefficient</td></tr><tr><td>决定系数</td><td>coefficient of determination</td></tr><tr><td>残差</td><td>residual</td></tr><tr><td>方差齐性</td><td>homogeneity of variance</td></tr><tr><td>t 检验</td><td>t-test</td></tr><tr><td>F 检验</td><td>F-test</td></tr><tr><td>χ² 检验</td><td>chi-square test</td></tr><tr><td>回归</td><td>regression</td></tr><tr><td>相关</td><td>correlation</td></tr><tr><td>频数 / 频率</td><td>frequency</td></tr><tr><td>直方图</td><td>histogram</td></tr><tr><td>散点图</td><td>scatterplot</td></tr><tr><td>箱线图</td><td>boxplot</td></tr><tr><td>条形图</td><td>bar chart</td></tr><tr><td>交叉表</td><td>crosstabulation（crosstab）</td></tr><tr><td>自变量</td><td>independent variable</td></tr><tr><td>因变量</td><td>dependent variable</td></tr><tr><td>分类变量</td><td>categorical variable</td></tr><tr><td>连续变量</td><td>continuous variable</td></tr><tr><td>名义 / 有序 / 标度</td><td>nominal / ordinal / scale</td></tr></tbody></table><p>用法提示：在 PSPP 语法窗口中，命令、子命令与变量名均为英文标识符，须保持原样，不可汉化；但在对话框标签、菜单与本书说明中常以中文呈现。读者在中文操作系统下阅读英文界面时，可借助本表快速对应对话框里的中文标签与底层英文术语。部分术语（如 nominal / ordinal / scale）同时出现在 Variable View 的&quot;度量标准&quot;列，建议与 <code>VARIABLE LEVEL</code> 命令对照理解，以免在分组或图形选项中混淆变量角色。</p><h2 id="附录-c-·-练习数据与素材说明" tabindex="-1">附录 C · 练习数据与素材说明 <a class="header-anchor" href="#附录-c-·-练习数据与素材说明" aria-label="Permalink to &quot;附录 C · 练习数据与素材说明&quot;">​</a></h2><p>本书各章的示例数据均为作者为演示语法而构想的虚构数据，仅用于说明操作步骤与输出解读，<strong>不可用于任何真实研究或论文结论</strong>。读者在练习时请始终将其视为教学素材，不要对数值本身做统计推断或外推。</p><p>GNU PSPP 官方手册随附了若干示例数据集，通常安装后位于 <code>/usr/local/share/pspp/examples</code> 目录，包括：</p><ul><li><code>physiology.sav</code>：生理测量类示例（如身高、体温等）；</li><li><code>personnel.sav</code>：人事/员工类示例（如部门、职级等）；</li><li><code>repairs.sav</code>：设备维修记录类示例（如故障时间、维修时长等）；</li><li><code>horticulture.sav</code>：园艺/栽培类示例（如产量、处理分组等）。</li></ul><p>这些文件同样是手册作者虚构的演示数据，仅用于熟悉命令，并非真实观测。读者可通过图形界面 File → Open 打开它们，或在语法中先用 <code>GET DATA</code>/<code>IMPORT</code> 读入后进行跟练。</p><p>若读者希望自建练习数据表，建议先在设计阶段确定字段，再录入或导入。一份典型的练习数据表可包含如下字段：</p><ul><li>一个可作为个案标识的编号字段（如 <code>id</code>，numeric）；</li><li>1~2 个分组/分类变量（如 <code>group</code>、<code>sex</code>，建议定义值标签，例如 0=女性、1=男性）；</li><li>2~3 个连续型测量变量（如 <code>height</code>、<code>weight</code>、<code>score</code>，numeric，保留适当小数位）；</li><li>如需练习缺失值处理，可预留一个会用特殊值（如 999）标记的字段，并配套 <code>MISSING VALUES</code> 定义。</li></ul><p>自建数据可在电子表格软件中先存为 ODS 或 CSV，再用 <code>GET DATA</code> 导入。导入 ODS 的语法要点：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET DATA /TYPE=ODS /FILE=&#39;file.ods&#39;</span></span>
<span class="line"><span>        /SHEET=NAME &#39;Sheet1&#39;</span></span>
<span class="line"><span>        /CELLRANGE=FULL</span></span>
<span class="line"><span>        /READNAMES=ON</span></span>
<span class="line"><span>        /ASSUMEDSTRWIDTH=32.</span></span></code></pre></div><p>导入 CSV/定界文本时改用 <code>/TYPE=TXT</code>，并以 <code>/DELIMITERS=</code> 指定分隔符（制表符用 <code>\\t</code>），用 <code>/FIRSTCASE=2</code> 跳过表头；<code>/VARIABLES=</code> 必须放在最后，并显式声明各列类型与宽度，以避免长文本被截断或表头误读为数据。</p><p>需要特别注意区域设置带来的两个常见隐患。其一，在部分语言环境（locale）下，数值小数点分隔符为逗号 <code>,</code>，录入 <code>12,5</code> 可能被误读；教学与练习建议采用英文 locale，或在格式中显式指定 <code>DOT8.3</code> 等后缀以固定小数点为 <code>.</code>。其二，字符串宽度默认偏窄，导入含长文本的列时务必显式设置 <code>ASSUMEDSTRWIDTH</code>，否则内容会被截断。</p><h2 id="附录-d-·-进阶学习资源" tabindex="-1">附录 D · 进阶学习资源 <a class="header-anchor" href="#附录-d-·-进阶学习资源" aria-label="Permalink to &quot;附录 D · 进阶学习资源&quot;">​</a></h2><p>GNU PSPP 是自由软件，其权威资料均以官方发布为准。建议读者将以下资源作为长期参考：</p><ul><li><strong>官方网站与手册</strong>：GNU PSPP 项目主页提供程序下载、版本说明与完整手册（Texinfo/HTML/PDF 等格式）。手册按命令分节点组织，是核查语法、子命令与缺省值的唯一权威来源。</li><li><strong>许可说明</strong>：PSPP 程序本身以 GNU GPL（GNU General Public License）发布；其文档以 GFDL（GNU Free Documentation License）发布。读者可在遵守许可条款的前提下自由使用、修改与再分发。</li><li><strong>社区与常见问题</strong>：PSPP 的用户邮件列表、发行版打包渠道与项目缺陷跟踪系统汇集了常见问题（FAQ）与版本动态。遇到界面或命令行为差异时，优先比对所装版本与官方手册。</li></ul><p>本书内容基于 PSPP <strong>2.0.1</strong> 左右版本编写，所引命令、子命令与缺省值以该版本官方手册为据。读者可在 <code>pspp</code> 文本界面启动时或 <code>psppire</code> 的关于对话框中查看具体版本号；命令行为与手册节点编号均可能随版本变化。需特别强调：PSPP 官方明确其仍处于&quot;work in progress&quot;（持续开发）状态，新版本可能增补命令、子命令或修正既有行为。<strong>所有命令的精确写法与可用性，最终请以读者所安装版本对应的官方手册为准</strong>；若手册与本书表述出现分歧，以官方手册为准。对尚未实现的过程（见附录 A），请勿期待在现有版本中直接可用。发现疑似缺陷时，可先在官方缺陷跟踪系统检索是否已有报告，再决定是否提交新报告，并附上可复现的语法与数据样例，以便维护者定位。</p>`,25)])])}const P=d(r,[["render",a]]);export{A as __pageData,P as default};
